    ["Displays the clock button on the minimap."] = "미니맵에 시계 버튼을 표시합니다.",
    ["Displays unit reactions and item qualities in tooltips and adds additional information to several other interfaces."] = "툴팁에 상대방의 반응과 아이템 품질을 표시하고 몇몇 인터페이스에 추가 정보를 표시합니다.",
    ["Do not apply a key."] = "단축키를 적용하지 않습니다.",
    ["Enable ambient sounds."] = "환경 소리 사용 여부를 설정합니다.",
    ["Enable background music."] = "배경음악 사용 여부를 설정합니다.",
    ["Enable detailed tooltips in the lower right hand corner of the screen."] = "화면 오른쪽 하단에 자세한 툴팁을 표시합니다.",
    ["Enable mature language filtering."] = "비속어 필터를 사용합니다.",
